export class Provider {
  readonly name = "demo";
  currentTurnRun: string | undefined;

openTurn(run: string) {
  if (this.currentTurnRun !== undefined) {
    throw new Error(`Cannot open turn ${run}: turn ${this.currentTurnRun} is still active`);
  }
  this.currentTurnRun = run;
}

